const items = $input.all();

return [
  {
    json: {
      articles: items.map(item => ({
        id: item.json.id,
        title: item.json.title,
        description: item.json.description,
        category: item.json.category,
        story_type: item.json.story_type,
        ai_score: item.json.ai_score,
        audience_interest: item.json.audience_interest,
        novelty: item.json.novelty,
        impact: item.json.impact,
        post_potential: item.json.post_potential,
        wow_factor: item.json.wow_factor,
        url: item.json.url
      }))
    }
  }
];

const input = $input.first().json;

// Если Deduplicate Articles завершился с ошибкой,
// не пропускаем ничего дальше
if (
  !input.output ||
  !Array.isArray(input.output.keep_ids)
) {
  return [];
}

const keepIds = input.output.keep_ids.map(Number);

const originalArticles = $('Get Candidates').all();

return originalArticles
  .filter(item => keepIds.includes(Number(item.json.id)))
  .map(item => ({
    json: item.json
  }));

