return aiItems
  .map((item, index) => {

    if (!item.json.output) {
      return null;
    }

    return {
      json: {
        article_id: articles[index].json.id,
        title: item.json.output.title,
        post_text: item.json.output.post_text,
        image_strategy: item.json.output.image_strategy,
        image_prompt: item.json.output.image_prompt,
        category: articles[index].json.category,
        source_url: articles[index].json.url,
      }
    };
  })
  .filter(item => item !== null);

const posts = $input.all();

return [
  {
    json: {
      recent_posts: posts.map(item => ({
        title: item.json.title,
        post_text: item.json.post_text
      }))
    }
  }
];

